      body: "수학은 영어와 달리 \"단원별 누적\" 학습이 핵심이에요. 1단원 (이차방정식) 정복 → 2단원 (이차함수) 시작이 답입니다. 1·2등급의 비밀은 \"단원별 6주 정복 사이클 + 일 루틴 + 주 루틴 + 월 루틴\" 4박자예요. 단원별 6주 사이클: 개념 1주 → 풀이 3주 → 응용 1주 → 심화·점검 1주. 일 루틴 (학년별 30분~2.5시간) + 주 루틴 (개념·풀이·점검 분배) + 월 루틴 (단원 1~2개 정복). 단순 시간 투자가 아니라 단원별 누적이 평생 자산이 돼요. 1:1 과외에서 루틴 첨삭이 효율적이에요."
