    checklist: ["학년별 적정 단계 정착 (초1·2 자연수·초3·4 분수·소수·초5·6 사칙·중1 정수·유리수)?","사칙연산 3법칙 (교환·결합·분배) 이해?","약수·배수·소인수분해 빈출 유형 정복?","절댓값·제곱근 정착?","음수 × 음수 = 양수 이유 설명 가능?"],
    checklistTitle: "수와 연산 체크리스트",
    checklistSub: "월 1회 점검",
    faqs: [
      {q: "초1 수학 어떻게 시작?", a: "초1 수학은 흥미 형성이 우선이에요. 한 자릿수 자연수 + 덧·뺄셈을 시각화 (구체물·블록·수직선·그림)로 자연스럽게 노출이 답이에요. 강요 X. 매일 15~20분 + 게임형 학습 + 학교 교과서 단원부터 챙기기. 무리하면 수학 거부감만 생겨요. 1:1 과외에서 흥미 형성 + 구구단 정착 코칭 추천."},
      {q: "초등생인데 음수가 너무 어려워요", a: "초등 단계 (5·6학년)에서 음수 도입은 자연스럽게 시작이 답이에요. 본격적인 음수 학습은 중1부터예요. 실생활 예시 활용: 온도 (영하·영상)·빚 (-)·해수면 기준 (위·아래)·엘리베이터 (지하층). 시각화 (수직선)도 효과적. 무리하면 수학 거부감만 생겨요. 1:1 과외에서 시각화 + 실생활 사례 학습 추천."},
      {q: "약수·배수가 헷갈려요", a: "약수·배수는 \"나누어 떨어지는가\"가 핵심이에요. 약수: 어떤 수를 나눠 떨어뜨리는 수 (12 ÷ 3 = 4·나머지 0이므로 3은 12의 약수). 배수: 어떤 수를 곱한 수 (3 × 4 = 12·12는 3의 배수). 두 개념은 짝꿍이에요. 시각화 (12 = 2 × 6 = 3 × 4 표) + 빈출 유형 (최대공약수·최소공배수) 정리가 답이에요."},
      {q: "절댓값과 제곱근 어떻게 정복?", a: "둘 다 \"거리\" 개념으로 이해가 답이에요. (1) 절댓값 |a|: 0으로부터의 거리 (|3| = 3, |-3| = 3). 거리는 항상 양수. (2) 제곱근 √a: 제곱하면 a가 되는 수 (√4 = 2). 시각화 (수직선·정사각형) + 빈출 유형 정리가 1·2등급의 비밀이에요. 1:1 과외에서 정리 추천."},
      {q: "수와 연산 다음 단계는?", a: "문자와 식 (algebra)이 다음 단계예요. 수의 자리에 문자 (x·y) 사용 → 다항식·인수분해·방정식 학습. 중1부터 본격 시작. 수와 연산이 정착되어야 문자와 식이 자연스러워요. 약점 있으면 1:1 과외에서 보강 후 진입 추천."},
    ],
