      body: "도형은 초1부터 시작되는 시각화·논리·계산의 종합 학습이에요. 공교육 도형 학습은 초1에 평면 도형 (삼각형·사각형·원) 인식부터. 단계적 발전이 답입니다. 핵심은 \"학년별 적정 단계 + 평면도형 성질 + 입체도형 부피·표면적 + 증명 (합동·닮음) + 좌표 (직선·원의 방정식)\" 4박자예요. 학년별 단계: 초1·2 (도형 인식·기본 모양) / 초3·4 (각·둘레·평행·수직) / 초5·6 (합동·대칭·넓이·부피) / 중1·2 (성질·작도·증명) / 중3·고1 (피타고라스·닮음·좌표). 단순 공식 암기 X. \"왜 이 도형이 이런 성질인가\" 시각화 + 논리적 사고가 1·2등급의 비밀이에요. 1:1 과외에서 시각화 + 증명 첨삭 추천."
