    checklist: ["수열의 극한 (수렴·발산·부정형) 정복?","함수의 극한 (좌·우극한) 이해?","연속성 (3가지 조건) 정착?","극한값 계산 (대수·삼각·지수·로그) 정복?","부정형 처리법 (약분·유리화·공식) 정착?"],
    checklistTitle: "극한 개념 체크리스트",
