    faqs: [
      {q: "극한이 너무 어려워요", a: "극한의 핵심은 \"가까이 가는 값\" 직관 + 정확한 계산이에요. 시각화 (그래프) + 부정형 처리법 정착 + 빈출 공식 외우기가 답이에요. 매주 빈출 극한 20문항 + 1:1 첨삭이 1·2등급의 비밀입니다. 6주 정착이면 자연스러워져요."},
      {q: "부정형 어떻게 처리?", a: "부정형 처리법 5가지: (1) 0/0: 약분·인수분해·유리화. (2) ∞/∞: 분자·분모 같은 차수로 나누기. (3) ∞-∞: 유리화·통분. (4) 0×∞: 분수로 변환. (5) 1^∞: e 활용. 매주 빈출 부정형 20문항 + 1:1 첨삭이 답이에요. 1·2등급의 결정적 도구예요."},
      {q: "좌·우극한 왜 따로 봐야 하나요?", a: "함수가 점 a에서 \"같은 값으로 수렴하는가\" 확인 때문이에요. 좌극한 ≠ 우극한이면 극한 X. 절댓값 함수 |x|의 x = 0에서 좌·우극한이 다름 (좌 -1·우 1). 계단함수도 마찬가지. 시각화 (그래프) + 1:1 첨삭이 답이에요."},
      {q: "극한 다음 단계는?", a: "미분 (derivative)이 다음 단계예요. 미분의 정의가 \"극한\"이라 극한 정착 안 되면 미분 무너져요. 함수 (function) → 극한 (limit) → 미분 (derivative) → 적분 (integral) 순서가 정석. 1:1 과외에서 단계별 학습 추천."},
    ],
