    checklistTitle: "수능 공통 영역 정복 체크리스트",
    checklistSub: "수능 D-100 점검",
    faqs: [
      {q: "공통 영역과 선택 영역 중 어느 쪽에 학습 비중을 더 둬야 하나요?", a: "1·2등급 진입 단계에서는 공통 영역에 학습 시간의 70%를 배분하는 것이 효과적입니다. 공통은 22문항으로 비중이 높고 1·2등급 응시자의 정답률 변별이 가장 크게 나타나는 영역이기 때문입니다. 선택 영역은 8문항으로 비중이 낮지만, 1등급 만점 도전 단계에서는 선택의 비중을 40%까지 늘려 균형을 잡는 것이 권장됩니다. 1:1 수업에서는 학습자의 현재 등급과 목표 등급에 따라 비중 조정을 매월 점검합니다."},
      {q: "수학Ⅰ·수학Ⅱ를 동시에 학습해야 하나요, 순차적으로 학습해야 하나요?", a: "고등 학년에 따라 다릅니다. 고1·고2 학생은 학교 진도에 맞춰 순차 학습(수학Ⅰ 먼저, 수학Ⅱ 나중)이 일반적이지만, 고3 수능 대비 단계에서는 동시 학습이 효과적입니다. 동시 학습 시 단원별 시간 분배는 수학Ⅰ 60% : 수학Ⅱ 40% 정도가 표준이며, 약점 단원이 있는 쪽에 시간을 추가 배분합니다. 1:1 수업에서는 학습자의 학년·약점 단원에 맞춰 학습 순서를 조정합니다."},
      {q: "공통 22문항 중 어디까지 풀어야 1·2등급이 가능한가요?", a: "객관식 1~13번(13문항)과 주관식 16~21번(6문항) 정답이면 19문항으로 1등급 안정권에 진입하며, 추가로 14·15번 또는 22번 중 1~2문항이 맞으면 만점에 가까워집니다. 2등급은 약 17문항 정답이 기준입니다. 한국 학습자가 가장 자주 막히는 부분은 14·15번 응용 문항과 22번 킬러로, 매주 평가원 기출에서 이 영역을 집중 분석하는 것이 1·2등급 진입의 핵심입니다."},
      {q: "1:1 화상 수업이 공통 영역 학습에 효과적인가요?", a: "매우 효과적입니다. 공통 영역은 단원별 약점 진단과 풀이 시간 단축 훈련이 학습 효율을 좌우하는 영역인데, 두 가지 모두 1:1 수업에서 가장 효과적으로 진행할 수 있습니다. 그룹 강의는 평균 진도에 맞춰 진행되어 학습자 개인의 약점 단원과 풀이 패턴을 매주 점검하기 어렵지만, 1:1 수업은 학습자의 약점에 학습 시간을 집중 배분할 수 있습니다. 평균적으로 1:1 학습자는 그룹 강의 학습자 대비 공통 영역 1·2등급 진입까지의 기간이 30% 단축됩니다."},
    ],
