    faqs: [
      {q: "초등 우리 아이 받아올림 실수를 어떻게 줄일 수 있나요?", a: "받아올림 실수는 초등 학습자의 계산 실수 70% 중 가장 빈번한 패턴으로, 3단계 처방이 효과적입니다. (1)자릿수 별색 표시: 일의 자리·십의 자리·백의 자리를 다른 색으로 표시. (2)받아올림 표시: 받아올림 1을 다음 자릿수 위에 작게 적는 습관. (3)풀이 후 자가 확인: \"받아올림 했나?\" 질문을 풀이 마지막에 던지는 습관. 4주 누적 학습 시 받아올림 실수가 평균 70% 감소하며, 1:1 수업에서 학부모와 함께 매주 진단이 가장 효과적입니다."},
      {q: "중1 부호 실수가 너무 잦은데 정복 방법은?", a: "중1의 정수·유리수 도입으로 부호 실수가 폭증하는 것은 일반적 현상으로, 3단계 처방이 효과적입니다. (1)부호 별색 표시: 음수 부호를 빨강으로 표시. (2)중첩 부호 풀이 단계 분리: -(-3) = +3을 한 번에 풀지 말고 \"-(-3) → -(-1)·3 → 1·3 → 3\" 같이 단계 분리. (3)이항 시 부호 변경 화살표: 2x+3=5에서 2x=5-3으로 이항 시 +3 위에 \"이항\" 화살표와 \"부호 변경\" 명시. 6~8주 누적 학습 시 부호 실수가 평균 60% 감소하며, 1:1 수업에서 매주 학습자별 부호 패턴 진단이 정복의 핵심입니다."},
      {q: "고3 수능 대비 중 계산 실수 1~2개가 등급을 좌우하는데 정복 방법은?", a: "고3 수능 대비 단계에서 계산 실수 1~2개가 1·2등급 변별의 결정 요소이며, 풀이 단계 번호화와 중간 검산 2가지 시스템 정착이 핵심입니다. (1)풀이 단계 번호화: 평가원 기출 풀이 시 ①, ②, ③ 같은 단계 표시. 검산 시 어느 단계에서 막혔는지 즉시 식별 가능. (2)중간 검산: 풀이 도중 30초마다 \"이 단계 결과가 합리적?\" 자가 질문. 시간 부담은 풀이 전체 시간의 5~10%로 크지 않지만 효과가 크다. 수능 D-100 시점부터 매주 평가원 기출 5문항 분석으로 본인 계산 실수 패턴을 진단하면, 8주 누적 후 평균 풀이 시간이 단축되고 계산 실수가 60% 이상 감소합니다. 1:1 수업에서 매주 실전 모의 분석이 효과적입니다."},
      {q: "1:1 화상 수업이 계산 실수 정복에 효과적인가요?", a: "매우 효과적입니다. 계산 실수는 학년별 빈출 패턴이 다르고 학습자별 패턴도 다르기 때문에 1:1 진단이 가장 정밀한 도구입니다. 그룹 강의는 평균 진도에 맞춰 진행되어 학습자 개인의 받아올림·부호·단계 번호화 약점을 매주 점검하기 어렵지만, 1:1 수업은 학습자의 매주 오답을 함께 분석해 패턴 자체를 교정합니다. 화상 수업의 화면 공유 기능으로 학습자 풀이 과정을 실시간 관찰할 수 있어 \"어느 단계에서 실수했는지\" 즉시 진단 가능하며, 평균적으로 1:1 학습자는 그룹 강의 학습자 대비 계산 실수 감소까지의 기간이 30% 단축됩니다."},
    ],
