    faqs: [
      {q: "초등 단위 오인 실수를 어떻게 줄일 수 있나요?", a: "초등 학습자의 단위 오인 실수는 단위 변환 개념 미숙으로 인한 일반적 현상이며, 2단계 처방이 효과적입니다. (1)단위 동그라미 습관: 문제 읽기 시 모든 단위(cm·m·g·kg·분·시간)에 빨강 동그라미 표시. (2)풀이 마지막 자가 확인: \"답의 단위 = 문제의 답 단위?\" 자가 질문. 추가로 단위 변환표(1m=100cm, 1kg=1000g 등)를 풀이지 옆에 적어두면 변환 실수 자체를 예방할 수 있습니다. 4~6주 누적 학습 시 단위 오인 실수가 평균 70% 감소하며, 1:1 수업에서 학부모와 함께 매주 점검이 효과적입니다."},
      {q: "고3 수능 \"모두 고르시오\" 다중 정답 실수를 어떻게 줄일 수 있나요?", a: "\"모두 고르시오\" 다중 정답 실수는 고등 학습자의 1·2등급 변별 결정 요소이며, 2단계 처방이 효과적입니다. (1)발문 키워드 표시: 객관식 발문의 \"모두\" 키워드를 빨강 동그라미로 표시(\"옳은 것을 (모두) 고르시오\" 같이). (2)정답 확인 자가 질문: 풀이 마지막에 \"문항이 다중 정답을 요구했나?\" \"내 답이 모든 정답을 포함했나?\" 2가지 자가 질문. 추가로 평가원 기출에서 다중 정답 문항을 5~10개 분리해 분석하면 패턴 인식이 정착됩니다. 8주 누적 학습 시 다중 정답 누락 실수가 평균 80% 감소하며, 1:1 수업에서 매주 평가원 기출 분석이 효과적입니다."},
      {q: "고등 수능형 문제의 \"단, ~제외\" 부가 조건 누락을 어떻게 줄일 수 있나요?", a: "\"단, ~제외\" 부가 조건 누락은 고등 학습자의 1·2등급 변별 결정 요소이며, 3단계 처방이 효과적입니다. (1)부가 조건 별표 표시: 문제 읽기 시 \"단\" \"제외\" \"~인 경우는\" 같은 키워드에 별표(★) 표시. (2)풀이 시작 시 부가 조건 재정리: 풀이지 상단에 \"부가 조건: ~\"을 별색으로 적어두기. (3)풀이 마지막 자가 확인: \"부가 조건 적용했나?\" \"답이 부가 조건을 만족하나?\" 2가지 자가 질문. 평가원 기출에서 부가 조건 문항을 10~15개 분리해 분석하면 패턴 인식이 정착되며, 1:1 수업에서 매주 부가 조건 문항 분석이 정복의 핵심입니다."},
      {q: "1:1 화상 수업이 문제 오독 정복에 효과적인가요?", a: "매우 효과적입니다. 문제 오독은 학년별 빈출 패턴이 다르고 학습자별 패턴도 다르며, 특히 고등 학습자의 논리 표현·부가 조건 오독은 1:1 진단이 가장 정밀합니다. 그룹 강의는 평균 진도에 맞춰 진행되어 학습자 개인의 단위·조건·논리 표현 약점을 매주 점검하기 어렵지만, 1:1 수업은 학습자의 매주 오답 5~10개를 함께 분석해 오독 패턴(특정 표현·특정 조건)을 진단합니다. 화상 수업의 화면 공유 기능으로 학습자의 문제 읽기 과정을 실시간 관찰할 수 있어 \"어느 표현에서 오독했는지\" 즉시 진단 가능하며, 평균적으로 1:1 학습자는 그룹 강의 학습자 대비 오독 실수 감소까지의 기간이 30% 단축됩니다."},
    ],
