    checklistTitle: "확통 심화 정복 체크리스트",
    checklistSub: "월 1회 점검",
    faqs: [
      {q: "조건부확률 응용이 너무 어려워요. 정복 방법은?", a: "조건부확률은 확통 심화의 가장 큰 변별 영역이지만, 사건 정의 작성과 응용 패턴 분석으로 정착 가능합니다. 효과적인 학습은 (1)풀이 첫 줄에 사건 A·B의 정의를 명시, (2)P(B|A)의 분모(P(A))와 분자(P(A∩B))를 별도로 계산하는 표 형식, (3)매주 평가원 기출의 조건부확률 5~10문항 분석입니다. 베이즈 정리 형태 문항은 \"원인 추정\" 구조를 인지하고 분모·분자를 명확히 구분하는 것이 핵심이며, 8주 누적 학습 시 정답률이 크게 향상됩니다. 1:1 수업에서 학습자별 약점 패턴 진단이 가장 빠른 회복 도구입니다."},
      {q: "정규분포 표준화의 부호 실수를 어떻게 줄일 수 있나요?", a: "정규분포 표준화의 부호 실수는 그래프 시각화 훈련으로 정착 가능합니다. 효과적인 학습은 (1)Z = (X-m)/σ 계산 후 표준정규분포 그래프 그리기, (2)Z값의 위치를 그래프에 표시 + 면적 음영 처리, (3)표준정규분포의 대칭성 활용(Z가 음수일 때 양수 영역의 면적과 동일), (4)P(a≤X≤b) 형태에서 두 Z값의 면적 차이 계산입니다. 매주 10문항 그래프 시각화 풀이로 4~6주 누적 학습 시 부호 실수가 평균 70% 감소하며, 1:1 수업에서 학습자별 시각화 약점 진단이 효과적입니다."},
      {q: "수능 D-100인데 확통 심화 진입이 늦지 않을까요?", a: "수능 D-100 시점에서 확통 심화 진입은 충분히 가능합니다. 확통은 학습 부담이 미적분 대비 약 70% 수준이라 정상 진도 학습자(4~6개월)보다 짧은 D-100(약 3개월) 시점에서 진입해도 1·2등급 안정화가 가능합니다. 기초 정착도 80% 이상이면 평가원 기출 5개년의 조건부확률·정규분포 응용 30~50문항 분석으로 D-30까지 변별 영역 정복이 가능하며, 1:1 수업에서 학습자별 진입 시점 진단과 매주 진도 점검이 정복의 핵심입니다."},
      {q: "1:1 화상 수업이 확통 심화 학습에 효과적인가요?", a: "매우 효과적입니다. 확통 심화는 사건 정의 작성 패턴과 정규분포 표준화 시각화 훈련이 학습 효율을 좌우하는 영역인데, 두 가지 모두 1:1 수업에서 가장 효과적으로 진행할 수 있습니다. 화상 수업의 화면 공유 기능으로 학습자의 풀이 과정과 그래프 시각화를 실시간 관찰할 수 있어 \"어느 단계에서 부호 실수가 발생했는지\" 즉시 진단 가능하며, 평균적으로 1:1 학습자는 그룹 강의 학습자 대비 확통 심화 정복까지의 기간이 30% 단축됩니다."},
    ],
