    checklistTitle: "기하 기초 정복 체크리스트",
    checklistSub: "월 1회 점검",
    faqs: [
      {q: "공간 시각화 능력이 약한데 기하를 선택해도 될까요?", a: "공간 시각화 능력은 훈련으로 향상 가능하지만, 약한 상태에서 기하를 선택하면 학습 효율이 미적분·확통 대비 떨어질 수 있습니다. 본인의 시각화 능력 진단은 평면도형 단면 그리기·정육면체 단면 시각화 5문항 정답률로 측정하며, 정답률이 60% 이하면 시각화 훈련 4~6주 후 재진단이 권장됩니다. 1:1 수업에서는 학습자의 시각화 능력 진단과 훈련 우선순위를 매주 조정합니다. 시각화 훈련 후에도 효율이 낮으면 미적분·확통으로 변경을 고려할 수 있습니다."},
      {q: "타원과 쌍곡선의 정의를 자꾸 혼동해요. 정복 방법은?", a: "타원(거리의 합 = 일정)과 쌍곡선(거리의 차 = 일정)의 정의 혼동은 이차곡선 학습의 가장 큰 약점이지만, 그래프 그리기 훈련으로 정착 가능합니다. 효과적인 학습은 (1)풀이 시작 전 이차곡선의 그래프를 정확히 그리기, (2)초점 두 개의 위치를 좌표에 명시, (3)정의를 한 줄로 명시(\"타원: F₁P + F₂P = 일정\" 또는 \"쌍곡선: |F₁P - F₂P| = 일정\")입니다. 매주 이차곡선 그래프 그리기 10문항 반복으로 4~6주 누적 학습 시 정답률이 크게 향상되며, 1:1 수업에서 학습자별 약점 패턴 진단이 가장 빠른 회복 도구입니다."},
      {q: "공간도형 단면 시각화를 어떻게 훈련하나요?", a: "공간도형 단면 시각화는 매주 훈련 분량과 풀이 과정 시각화 습관이 정복의 핵심입니다. 효과적인 학습은 (1)풀이 시작 전 3단계 시각화 (전체 도형 그리기·단면 위치 표시·좌표 설정), (2)단면의 형태(삼각형·사각형·육각형 등)를 명시, (3)매주 평가원 기출의 공간도형 단면 시각화 10문항 분석입니다. 8주 누적 학습 시 정답률이 크게 향상되며, 화상 수업의 화면 공유 기능으로 학습자의 풀이 과정을 실시간 관찰할 수 있어 \"어느 단계에서 시각화가 막혔는지\" 즉시 진단 가능합니다."},
      {q: "1:1 화상 수업이 기하 기초 학습에 효과적인가요?", a: "매우 효과적입니다. 기하 기초는 공간 시각화 능력 진단과 이차곡선 그래프 그리기 훈련이 학습 효율을 좌우하는 영역인데, 두 가지 모두 1:1 수업에서 가장 효과적으로 진행할 수 있습니다. 화상 수업의 화면 공유 기능으로 학습자의 도형 그리기 과정을 실시간 관찰할 수 있어 \"어느 단계에서 시각화가 막혔는지\" 즉시 진단 가능하며, 평균적으로 1:1 학습자는 그룹 강의 학습자 대비 기하 기초 정착까지의 기간이 30% 단축됩니다. 무엇보다 시각화 능력 자체가 향상되어 다른 단원 학습에도 긍정적 영향을 미칩니다."},
    ],
